/// Node predicates of the SelectionDAG patterns (`PatFrag`s), their C++ as LLVM writes it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Pred {
    /// `return N->hasOneUse();`
    AndSu,
    /// `return N->getOpcode() != ISD::TRUNCATE && N->getOpcode() != TargetOpcode::EXTRACT_SUBREG && N->getOpcode() != ISD::CopyFromReg && N->getOpcode() != ISD::AssertSext && N->getOpcode() != ISD::AssertZext && N->getOpcode() != ISD::AssertAlign && N->getOpcode() != ISD::FREEZE && !((N->getOpcode() == X86ISD::BSF || N->getOpcode() == X86ISD::BSR) && (!N->getOperand(0).isUndef() && !isa<ConstantSDNode>(N->getOperand(0))));`
    Def32,
    /// `extload`
    Extload,
    /// `extloadi1`
    Extloadi1,
    /// `extloadi16`
    Extloadi16,
    /// `LoadSDNode *LD = cast<LoadSDNode>(N); ISD::LoadExtType ExtType = LD->getExtensionType(); if (ExtType != ISD::EXTLOAD) return false; if (LD->getMemoryVT() == MVT::i32) return true; return LD->getAlign() >= 4 && LD->isSimple();`
    Extloadi64i32,
    /// `extloadi8`
    Extloadi8,
    /// `return isInt<32>(Imm);`
    I64immSExt32,
    /// `return !shouldAvoidImmediateInstFormsForSize(N);`
    I64immSExt32Su,
    /// `return isUInt<32>(Imm);`
    I64immZExt32,
    /// `return isSExtAbsoluteSymbolRef(32, N);`
    I64relocImmSExt32,
    /// `return !shouldAvoidImmediateInstFormsForSize(N);`
    I64relocImmSExt32Su,
    /// `return !shouldAvoidImmediateInstFormsForSize(N);`
    ImmSu,
    /// `return Imm >= 0xff00 && Imm <= 0xffff;`
    Immff00Ffff,
    /// `load`
    Load,
    /// `LoadSDNode *LD = cast<LoadSDNode>(N); ISD::LoadExtType ExtType = LD->getExtensionType(); if (ExtType == ISD::NON_EXTLOAD) return true; if (ExtType == ISD::EXTLOAD && EnablePromoteAnyextLoad) return LD->getAlign() >= 2 && LD->isSimple(); return false;`
    Loadi16,
    /// `LoadSDNode *LD = cast<LoadSDNode>(N); ISD::LoadExtType ExtType = LD->getExtensionType(); if (ExtType == ISD::NON_EXTLOAD) return true; if (ExtType == ISD::EXTLOAD && EnablePromoteAnyextLoad) return LD->getAlign() >= 4 && LD->isSimple(); return false;`
    Loadi32,
    /// `LoadSDNode *LD = cast<LoadSDNode>(N); ISD::LoadExtType ExtType = LD->getExtensionType(); return ExtType == ISD::NON_EXTLOAD || ExtType == ISD::EXTLOAD || ExtType == ISD::ZEXTLOAD;`
    Loadi8,
    /// `return cast<StoreSDNode>(N)->isNonTemporal();`
    Nontemporalstore,
    /// `return !shouldAvoidImmediateInstFormsForSize(N);`
    RelocImm16Su,
    /// `return !shouldAvoidImmediateInstFormsForSize(N);`
    RelocImm32Su,
    /// `return !shouldAvoidImmediateInstFormsForSize(N);`
    RelocImm8Su,
    /// `sextload`
    Sextload,
    /// `sextloadi16`
    Sextloadi16,
    /// `sextloadi32`
    Sextloadi32,
    /// `sextloadi8`
    Sextloadi8,
    /// `return isUnneededShiftMask(N, 4);`
    ShiftMask16,
    /// `return isUnneededShiftMask(N, 5);`
    ShiftMask32,
    /// `return isUnneededShiftMask(N, 6);`
    ShiftMask64,
    /// `return N->hasOneUse();`
    SrlSu,
    /// `store`
    Store,
    /// `return N->hasOneUse();`
    TruncSu,
    /// `unindexedload`
    Unindexedload,
    /// `unindexedstore`
    Unindexedstore,
    /// `zextload`
    Zextload,
    /// `zextloadi1`
    Zextloadi1,
    /// `zextloadi16`
    Zextloadi16,
    /// `zextloadi32`
    Zextloadi32,
    /// `zextloadi8`
    Zextloadi8,
}

